/**
 * Google Chat Node - Version 1
 * Discriminator: resource=message, operation=get
 */


interface Credentials {
  googleApi: CredentialReference;
  googleChatOAuth2Api: CredentialReference;
}

/** Get a membership */
export type GoogleChatV1MessageGetParams = {
  resource: 'message';
  operation: 'get';
  authentication?: 'oAuth2' | 'serviceAccount' | Expression<string>;
/**
 * Resource name of the message. Format: spaces/{space}/messages/{message}. For system-assigned IDs, use the full message name, such as spaces/AAAAAAAAAAA/messages/BBBBBBBBBBB.BBBBBBBBBBB. For custom IDs, use spaces/AAAAAAAAAAA/messages/client-custom-name.
 */
    messageId: string | Expression<string>;
};

export type GoogleChatV1MessageGetOutput = {
  argumentText?: string;
  createTime?: string;
  formattedText?: string;
  name?: string;
  sender?: {
    displayName?: string;
    name?: string;
    type?: string;
  };
  space?: {
    lastActiveTime?: string;
    membershipCount?: {
      joinedDirectHumanUserCount?: number;
    };
    name?: string;
    spaceHistoryState?: string;
    spaceThreadingState?: string;
    spaceType?: string;
    spaceUri?: string;
    type?: string;
  };
  text?: string;
  thread?: {
    name?: string;
  };
};

export type GoogleChatV1MessageGetNode = {
  type: 'n8n-nodes-base.googleChat';
  version: 1;
  config: NodeConfig<GoogleChatV1MessageGetParams> & { credentials?: Credentials };
  output?: Items<GoogleChatV1MessageGetOutput>;
};